import{_ as n,o as s,c as a,f as o,a as e}from"./app-v4ODCOL5.js";const t={},c=e(`<h2 id="第-2-章-作用域、闭包、this-与原型链" tabindex="-1"><a class="header-anchor" href="#第-2-章-作用域、闭包、this-与原型链" aria-hidden="true">#</a> 第 2 章 作用域、闭包、this 与原型链</h2><h3 id="q1-说说你对作用域的理解-js-里有哪几种作用域" tabindex="-1"><a class="header-anchor" href="#q1-说说你对作用域的理解-js-里有哪几种作用域" aria-hidden="true">#</a> Q1 说说你对作用域的理解，JS 里有哪几种作用域？</h3><p><strong>考察点</strong>：能不能一句话说清作用域的本质，并准确列出三种作用域及其边界，而不是背名词。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：作用域（Scope）就是变量和函数的可访问范围，JS 里有全局作用域、函数作用域和块级作用域三种。</p></blockquote><ol><li>全局作用域：脚本最外层，页面关闭才销毁。顶层用 <code>var</code> 声明的变量会成为全局对象 <code>window</code> 的属性。</li><li>函数作用域：函数内部声明的变量只在该函数内可见；每调用一次函数，就创建一份全新的作用域，互不干扰。</li><li>块级作用域：<code>{}</code>、<code>if</code>、<code>for</code> 这种代码块，只有 <code>let</code>/<code>const</code> 声明才受它约束，<code>var</code> 不受约束。</li><li>作用域是<strong>静态</strong>的：函数在哪里定义，它的作用域就定死了，跟它在哪里被调用没有关系。这一点是理解闭包的前提。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：作用域是运行时创建的吗？答：不是，词法环境在编译（解析）阶段就确定；运行时创建的是执行上下文（Execution Context）。</li><li>陷阱：说「<code>var</code> 没有作用域」。正确说法是「<code>var</code> 没有块级作用域，它是函数作用域的」。</li><li>陷阱：把作用域和 <code>this</code> 混在一起。作用域看定义位置，<code>this</code> 看调用方式，两者是两套机制。</li></ul><h3 id="q2-什么是作用域链-引擎找一个变量的时候具体是怎么走的" tabindex="-1"><a class="header-anchor" href="#q2-什么是作用域链-引擎找一个变量的时候具体是怎么走的" aria-hidden="true">#</a> Q2 什么是作用域链？引擎找一个变量的时候具体是怎么走的？</h3><p><strong>考察点</strong>：能否把「变量查找」讲成一条可复述的路径，而不是含糊地说「往外层找」。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：作用域链是当前作用域到全局作用域串起来的一串词法环境，查找变量时从最内层逐级向外，找到就停，全都没有就报 <code>ReferenceError</code>。</p></blockquote><ol><li>函数在<strong>定义</strong>时，内部属性 <code>[[Environment]]</code> 会记住自己所在的那层词法环境，形成静态的链条。</li><li>查找顺序：当前环境 → 外层环境 → … → 全局环境。在某一层命中同名标识符就立即停止，这就是内层「遮蔽」外层同名变量的原因。</li><li>读不到时报 <code>ReferenceError</code>；但<strong>赋值</strong>读不到时，非严格模式会悄悄创建一个全局变量，这是最常见的意外全局污染。</li><li>作用域链决定闭包能记住哪些变量；属性查找走的是另一套机制——原型链。二者不要混为一谈。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：作用域链和原型链有什么区别？答：作用域链找变量，函数定义时就确定；原型链找对象属性，运行时通过 <code>[[Prototype]]</code> 逐级向上。</li><li>陷阱：把 <code>obj.name</code> 的查找说成「沿作用域链找 <code>name</code>」。<code>obj</code> 是变量走作用域链，<code>.name</code> 是属性走原型链。</li><li>追问：闭包为什么能访问外层变量？答：因为它的 <code>[[Environment]]</code> 指向外层词法环境，链条没有断。</li></ul><h3 id="q3-什么是词法作用域-它和动态作用域有什么区别" tabindex="-1"><a class="header-anchor" href="#q3-什么是词法作用域-它和动态作用域有什么区别" aria-hidden="true">#</a> Q3 什么是词法作用域？它和动态作用域有什么区别？</h3><p><strong>考察点</strong>：考察是否真正理解 JS 作用域是「按写代码的位置」决定，而不是「按调用位置」决定。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：词法作用域（Lexical Scope）指作用域由代码书写位置决定，JS 用的就是词法作用域；动态作用域（Dynamic Scope）则由调用位置决定，JS 不用它，只有 <code>this</code> 带有这种动态色彩。</p></blockquote><ol><li>词法作用域也叫静态作用域：函数定义在哪一层，就能访问那一层及更外层的变量，与谁调用它无关。</li><li>动态作用域：函数里访问变量要看「谁调用了我」。Bash、早期的 Lisp 是这种模型，JS 不是。</li><li>JS 里最接近动态作用域的只有 <code>this</code>——<code>this</code> 的值由调用点决定，所以很多人误以为 JS 是动态作用域。</li><li>实操意义：变量遮蔽（shadowing）和闭包都是词法作用域的直接结果，读懂代码时只看嵌套结构就够了。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">var</span> a <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">bar</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>  <span class="token comment">// 只看定义位置：外层是全局，a 是 1</span>
<span class="token keyword">function</span> <span class="token function">foo</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">var</span> a <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token function">bar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// 谁调用都不影响</span>
<span class="token function">foo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1，不是 2</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>this</code> 算不算动态作用域？答：<code>this</code> 是动态的，但它不是作用域机制，只是函数的一个隐式参数。</li><li>陷阱：答成「JS 既是词法作用域又是动态作用域」，会把面试官引向追问而答不实。</li></ul><h3 id="q4-什么是变量提升-函数声明和变量声明的提升有什么不一样" tabindex="-1"><a class="header-anchor" href="#q4-什么是变量提升-函数声明和变量声明的提升有什么不一样" aria-hidden="true">#</a> Q4 什么是变量提升？函数声明和变量声明的提升有什么不一样？</h3><p><strong>考察点</strong>：考察 hoisting 的准确机制，以及函数声明优先于变量声明这个常考细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：变量提升（Hoisting）指声明在代码执行前就被处理：<code>var</code> 只提升声明、值是 <code>undefined</code>；函数声明连函数体一起提升，所以能在声明之前调用。</p></blockquote><ol><li>引擎在进入作用域时会先做一轮「收集」：把 <code>var</code> 声明的标识符登记好（值为 <code>undefined</code>），把函数声明整个提前。</li><li>因此 <code>console.log(a)</code> 在 <code>var a = 1</code> 之前执行输出 <code>undefined</code>，不报错；但函数声明可以提前调用。</li><li>同名冲突时，<strong>函数声明优先级高于 <code>var</code></strong>：<code>var foo</code> 不会覆盖已提升的函数 <code>foo</code>；但如果后面有 <code>foo = 1</code> 这样的赋值，运行时还是会被改写。</li><li>块级作用域里的函数声明在 ES6 严格模式（含模块、<code>class</code> 内部）下按块提升，只在块内可见；非严格模式行为是历史遗留的兼容写法，不要依赖。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>a<span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// undefined</span>
<span class="token function">foo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>               <span class="token comment">// &#39;ok&#39;，函数声明连函数体一起提升</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>foo<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// [Function: foo]</span>
<span class="token keyword">var</span> a <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">foo</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;ok&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：提升是「把代码挪到顶部」吗？答：不是真的挪代码，是执行前的声明收集，理解成「声明提前、赋值留在原地」。</li><li>陷阱：说 <code>let</code> 也提升。<code>let</code>/<code>const</code> 同样被登记，但访问被禁止，这就是暂时性死区。</li><li>陷阱：以为 <code>var a = function () {}</code> 也能提前调用。函数表达式只提升变量名，此时值是 <code>undefined</code>。</li></ul><h3 id="q5-什么是暂时性死区-tdz-它有什么用" tabindex="-1"><a class="header-anchor" href="#q5-什么是暂时性死区-tdz-它有什么用" aria-hidden="true">#</a> Q5 什么是暂时性死区（TDZ）？它有什么用？</h3><p><strong>考察点</strong>：TDZ 是 <code>let</code>/<code>const</code> 最容易被漏掉的细节，也是面试官判断基础扎不扎实的常用题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：暂时性死区（Temporal Dead Zone）指从进入作用域到 <code>let</code>/<code>const</code> 声明真正执行之间，访问该变量会直接抛 <code>ReferenceError</code>——变量已登记但被禁止访问。</p></blockquote><ol><li>表现：在声明之前读、写、甚至 <code>typeof</code> 都会抛错，这一点和「未声明的变量」不同（未声明变量的 <code>typeof</code> 返回 <code>&#39;undefined&#39;</code>）。</li><li>用途一：把「用错顺序」从静默的 <code>undefined</code> 变成显式报错，逼出代码里的时序问题。</li><li>用途二：让 <code>const</code> 的「必须初始化」有意义；也保证了块级作用域和 <code>for</code> 循环每轮独立绑定的正确性。</li><li>注意 <code>var</code> 没有 TDZ；函数声明也没有（整个函数体都提升了）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> a<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// ReferenceError（对比：typeof 未声明变量是 &#39;undefined&#39;）</span>
<span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：TDZ 是「提升」的反面吗？答：不是。二者都做声明登记，区别是 TDZ 期间禁止访问，而 <code>var</code> 期间返回 <code>undefined</code>。</li><li>陷阱：认为「TDZ 只在块内生效，函数参数不算」。函数默认参数也有 TDZ 行为，先用的参数不能引用后声明的参数。</li></ul><h3 id="q6-var、let、const-在作用域上到底差在哪" tabindex="-1"><a class="header-anchor" href="#q6-var、let、const-在作用域上到底差在哪" aria-hidden="true">#</a> Q6 <code>var</code>、<code>let</code>、<code>const</code> 在作用域上到底差在哪？</h3><p><strong>考察点</strong>：最高频的对照题，要求能脱口而出成表格，而不是零散地说。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>var</code> 是函数作用域、可重复声明、会提升为 <code>undefined</code> 且能挂到 <code>window</code>；<code>let</code>/<code>const</code> 是块级作用域、不可重复声明、有 TDZ；其中 <code>const</code> 还要求声明即初始化且绑定不可改。</p></blockquote><table><thead><tr><th>维度</th><th><code>var</code></th><th><code>let</code></th><th><code>const</code></th></tr></thead><tbody><tr><td>作用域</td><td>函数作用域</td><td>块级作用域</td><td>块级作用域</td></tr><tr><td>变量提升</td><td>提升，值为 <code>undefined</code></td><td>提升但进 TDZ</td><td>提升但进 TDZ</td></tr><tr><td>重复声明</td><td>允许</td><td>报错</td><td>报错</td></tr><tr><td>初始值</td><td>可省略</td><td>可省略</td><td>必须给</td></tr><tr><td>顶层是否挂 <code>window</code></td><td>是（script 中）</td><td>否</td><td>否</td></tr><tr><td>能否重新赋值</td><td>能</td><td>能</td><td>不能</td></tr></tbody></table><ol><li>关键差异只有两条根：<strong>作用域粒度</strong>和<strong>声明约束</strong>，其余细节都是这两条的衍生。</li><li>工程建议：默认用 <code>const</code>，需要重新赋值时用 <code>let</code>，<code>var</code> 只出现在维护老代码时。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>const</code> 到底锁住了什么？答：锁的是绑定（引用），不是值本身，见下一题。</li><li>陷阱：说「<code>let</code> 不提升」。准确说法是有提升但进 TDZ，不能访问。</li><li>陷阱：在 <code>for</code> 里混用 <code>var</code> 与 <code>let</code> 导致闭包取值不同（见循环那一题）。</li></ul><h3 id="q7-const-声明的对象-为什么还能改属性-怎么让它真的不能改" tabindex="-1"><a class="header-anchor" href="#q7-const-声明的对象-为什么还能改属性-怎么让它真的不能改" aria-hidden="true">#</a> Q7 <code>const</code> 声明的对象，为什么还能改属性？怎么让它真的不能改？</h3><p><strong>考察点</strong>：考察是否分得清「绑定不可变」和「值不可变」，以及是否知道冻结的深浅。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>const</code> 保证的是<strong>绑定不可重新赋值</strong>，不是值不可变；对象是引用类型，修改属性并没有改绑定，所以允许。</p></blockquote><ol><li><code>const obj = {}</code> 之后 <code>obj = {}</code> 报 TypeError；但 <code>obj.a = 1</code>、<code>obj.a++</code>、<code>delete obj.a</code> 都合法。</li><li>想要真正不可变要用 <code>Object.freeze(obj)</code>，但它只是<strong>浅冻结</strong>：嵌套对象的属性仍然可改。</li><li>深冻结要递归处理嵌套对象，或直接用不可变数据方案（如 Immer 这类库）来保证。</li><li>冻结还会影响数组：长度不可改，<code>push</code>、<code>sort</code> 这类会静默失败（严格模式下抛错）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> o <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">a</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token literal-property property">inner</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">b</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
Object<span class="token punctuation">.</span><span class="token function">freeze</span><span class="token punctuation">(</span>o<span class="token punctuation">)</span><span class="token punctuation">;</span>
o<span class="token punctuation">.</span>a <span class="token operator">=</span> <span class="token number">9</span><span class="token punctuation">;</span>          <span class="token comment">// 静默失败（严格模式抛 TypeError）</span>
o<span class="token punctuation">.</span>inner<span class="token punctuation">.</span>b <span class="token operator">=</span> <span class="token number">9</span><span class="token punctuation">;</span>    <span class="token comment">// 仍然成功：浅冻结不保护嵌套对象</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那原始类型呢？答：原始类型本来不可变，<code>const x = 1; x = 2</code> 报错是因为绑定不能改。</li><li>陷阱：把 <code>const</code> 当成「常量值」的保证，说出「<code>const</code> 对象的属性改不了」会被立刻用一行代码问穿。</li></ul><h3 id="q8-顶层用-var-和用-let-声明-差别在哪" tabindex="-1"><a class="header-anchor" href="#q8-顶层用-var-和用-let-声明-差别在哪" aria-hidden="true">#</a> Q8 顶层用 <code>var</code> 和用 <code>let</code> 声明，差别在哪？</h3><p><strong>考察点</strong>：考察全局环境的两套记录：对象环境记录与声明式环境记录。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：在传统脚本（script）中，顶层的 <code>var</code> 和函数声明会变成 <code>window</code> 的属性，而 <code>let</code>/<code>const</code>/<code>class</code> 只存在于全局的声明式环境记录里，不会成为 <code>window</code> 的属性。</p></blockquote><ol><li><code>var a = 1</code> 之后 <code>window.a === 1</code> 成立，<code>delete window.a</code> 也不生效（属性不可配置）。</li><li><code>let b = 1</code> 之后 <code>window.b</code> 是 <code>undefined</code>，但直接写 <code>b</code> 能访问，它只对脚本可见。</li><li>在 ES 模块里，顶层 <code>var</code> 同样<strong>不会</strong>挂到 <code>window</code>，模块有自己独立的作用域。</li><li><code>function f(){}</code> 在脚本顶层也会挂到 <code>window</code>；<code>class C {}</code> 不会。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么会有这个设计？答：<code>let</code> 就是为了修掉「全局变量污染 <code>window</code>、可能覆盖同名全局属性」这个老问题。</li><li>陷阱：在全局用 <code>let a</code> 后又写 <code>window.a = 1</code>，两者互不干扰，排查线上问题时最容易被这个坑绕晕。</li></ul><h3 id="q9-什么是闭包-闭包是怎么形成的" tabindex="-1"><a class="header-anchor" href="#q9-什么是闭包-闭包是怎么形成的" aria-hidden="true">#</a> Q9 什么是闭包？闭包是怎么形成的？</h3><p><strong>考察点</strong>：最经典的必答题，要求定义准确、条件清楚，且能说出「闭包不是函数本身」这个层次。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：闭包（Closure）是<strong>函数加上它定义时所在的词法环境</strong>，所以函数在外层函数已经执行完之后，仍然能访问外层的变量。</p></blockquote><ol><li>准确说法：闭包 = 函数 + 对它定义位置的词法环境的引用。每个函数都带 <code>[[Environment]]</code>，所以严格说 JS 里处处是闭包，面试关注的是「跨越了函数生命周期还被访问」的那种。</li><li>形成条件（缺一不可）：① 存在函数嵌套；② 内层函数引用了外层函数的变量；③ 内层函数逃逸到外层函数之外（被返回、被挂到事件/定时器上）。</li><li>关键点：闭包保存的是<strong>变量本身</strong>，不是变量的快照。外层变量后来怎么变，闭包读到就是什么，这也是循环里打印同一个值的根源。</li><li>作用：延长变量生命周期、实现数据私有与状态保持（计数器、缓存、防抖节流都靠它）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">makeCounter</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">++</span>count<span class="token punctuation">;</span>   <span class="token comment">// 内层函数引用了 count，且被返回 → 闭包</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> c <span class="token operator">=</span> <span class="token function">makeCounter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">c</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1</span>
<span class="token function">c</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2，count 没有被回收，状态被保留</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：闭包是什么时候创建的？答：函数创建时就跟着词法环境一起形成，不是在调用时。</li><li>陷阱：说「闭包就是一个函数」。漏掉词法环境，就等于没答到点上。</li><li>陷阱：说「只有返回函数才有闭包」。传给 <code>setTimeout</code>、注册成事件回调，同样是闭包。</li></ul><h3 id="q10-闭包为什么能让变量不被回收-引擎真的把整个作用域都留下了吗" tabindex="-1"><a class="header-anchor" href="#q10-闭包为什么能让变量不被回收-引擎真的把整个作用域都留下了吗" aria-hidden="true">#</a> Q10 闭包为什么能让变量不被回收？引擎真的把整个作用域都留下了吗？</h3><p><strong>考察点</strong>：区分「背结论」和「懂引擎实现」，这是拉开差距的深挖题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：闭包函数的内部属性 <code>[[Environment]]</code> 一直引用着创建它的词法环境，环境记录对象因此从根可达、不被回收；但现代引擎只会保留真正被闭包引用到的变量，不会留下整个作用域。</p></blockquote><ol><li>垃圾回收判断的是「可达性」：闭包函数本身可达（被变量、事件、定时器引用），它引用的环境记录就可达，里面被引用的变量就不会被回收。</li><li>V8 的优化：只有被内层函数引用的变量才会被分配到堆上的上下文对象（Context）里，其余变量随栈帧一起销毁。所以「闭包会保留整个父级作用域」是过时说法。</li><li>代价也来自这里：如果一个闭包只用了小变量，却顺手引用了外层的大数组/大 DOM 对象，那个大对象才会被真正拖住。</li><li>想让闭包尽快释放状态，就把引用置空（如定时器 <code>clearTimeout</code>、事件 <code>removeEventListener</code>），或改用 <code>WeakMap</code>。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>eval</code> 会不会影响这个优化？答：会，含 <code>eval</code> 或 <code>with</code> 的作用域无法做静态分析，引擎只能保守地保留整个作用域。</li><li>陷阱：说「闭包必然造成内存泄漏」。闭包本身是正常特性，只有「不再需要却被长期持有」才算泄漏。</li></ul><h3 id="q11-怎么用闭包实现私有变量-为什么不直接用下划线约定" tabindex="-1"><a class="header-anchor" href="#q11-怎么用闭包实现私有变量-为什么不直接用下划线约定" aria-hidden="true">#</a> Q11 怎么用闭包实现私有变量？为什么不直接用下划线约定？</h3><p><strong>考察点</strong>：考察闭包最基本的工程用法，以及「约定」和「真正不可访问」的区别。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：把变量放在外层函数里、只返回操作它的方法，外部就只能通过方法读写，无法直接触碰变量，这是真正的数据私有；下划线只是团队约定，拦不住任何人。</p></blockquote><ol><li>闭包方案：变量在函数作用域内，外部拿不到引用，只能走暴露出去的方法，读写行为完全可控（可做校验、可只读）。</li><li>下划线方案（<code>this._count</code>）：仍在实例上，外部 <code>obj._count = 999</code> 就能改，只是「大家约定不要动」。</li><li>现代替代：<code>class</code> 的私有字段 <code>#count</code>，语言层面拦截，<code>obj.#count</code> 直接语法错误；也可以用 <code>WeakMap</code> 把私有数据挂在实例之外。</li><li>取舍：闭包方案每个实例都持有一份函数，实例多时内存开销略大；<code>#</code> 字段更省、也更直观。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">createCounter</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>                       <span class="token comment">// 外部无法直接访问</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span>
    <span class="token function-variable function">inc</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">++</span>count<span class="token punctuation">,</span>
    <span class="token keyword">get</span> <span class="token function">value</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> count<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>     <span class="token comment">// 只读暴露</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> c <span class="token operator">=</span> <span class="token function">createCounter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
c<span class="token punctuation">.</span><span class="token function">inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
c<span class="token punctuation">.</span>count <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">;</span>   <span class="token comment">// 无效，只是新增了一个普通属性</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>WeakMap</code> 方案怎么写？答：模块级 <code>const priv = new WeakMap()</code>，构造时 <code>priv.set(this, {count: 0})</code>，方法里 <code>priv.get(this)</code>。</li><li>陷阱：说 Symbols 能实现私有。<code>Object.getOwnPropertySymbols</code> 一样能拿到，只算「不显眼」，不算私有。</li></ul><h3 id="q12-手写一个防抖-debounce-并说明为什么它必须用闭包。" tabindex="-1"><a class="header-anchor" href="#q12-手写一个防抖-debounce-并说明为什么它必须用闭包。" aria-hidden="true">#</a> Q12 手写一个防抖（debounce），并说明为什么它必须用闭包。</h3><p><strong>考察点</strong>：高频手写题，重点看 <code>this</code> 与参数是否透传、定时器是否正确清理。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：防抖是「事件停止触发 delay 毫秒后才执行一次」，必须用闭包保存那个共享的 timer 句柄，否则每次调用都会新建定时器，等于没防抖。</p></blockquote><ol><li>核心机制：每次触发先清掉上一个定时器，再起一个新的；只有最后一次能活到执行。</li><li>必须透传 <code>this</code> 和参数：回调里用 <code>fn.apply(this, args)</code>，否则在对象方法或事件里会丢 <code>this</code>。</li><li>立即执行版（<code>immediate</code>）：第一次立刻执行，之后在等待期内不再执行，适合按钮防重复提交。</li><li>常见加分项：返回的函数上挂 <code>cancel</code>/<code>flush</code>，方便在组件卸载时清理，避免定时器泄漏。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> delay <span class="token operator">=</span> <span class="token number">300</span><span class="token punctuation">,</span> immediate <span class="token operator">=</span> <span class="token boolean">false</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>                       <span class="token comment">// 闭包保存，跨调用共享</span>
  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>immediate<span class="token punctuation">)</span> <span class="token punctuation">{</span>                      <span class="token comment">// 首次立即执行，冷却期内忽略</span>
      <span class="token keyword">if</span> <span class="token punctuation">(</span>timer<span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span>
      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>
      timer <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> delay<span class="token punctuation">)</span><span class="token punctuation">;</span>
      <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>timer<span class="token punctuation">)</span> <span class="token function">clearTimeout</span><span class="token punctuation">(</span>timer<span class="token punctuation">)</span><span class="token punctuation">;</span>
    timer <span class="token operator">=</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>
      timer <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span> delay<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：输入框搜索用防抖还是节流？答：输入联想用防抖（要等用户停下），滚动加载用节流（要持续响应）。</li><li>陷阱：用普通函数而不是保留 <code>this</code>，在 <code>obj.method = debounce(obj.method, 300)</code> 之后 <code>this</code> 丢失。</li></ul><h3 id="q13-手写节流-throttle-它和防抖的区别是什么" tabindex="-1"><a class="header-anchor" href="#q13-手写节流-throttle-它和防抖的区别是什么" aria-hidden="true">#</a> Q13 手写节流（throttle），它和防抖的区别是什么？</h3><p><strong>考察点</strong>：考察是否能同时把手写题和对比题答清，并说清首尾两次执行的处理。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：节流是「在 interval 时间内最多执行一次」，保证频率上限；防抖是「等安静下来再执行」，保证只执行最后一次。</p></blockquote><table><thead><tr><th>维度</th><th>防抖 debounce</th><th>节流 throttle</th></tr></thead><tbody><tr><td>触发时机</td><td>停止触发后</td><td>固定时间间隔内最多一次</td></tr><tr><td>执行次数</td><td>通常只 1 次</td><td>持续触发期间会多次</td></tr><tr><td>典型场景</td><td>搜索联想、窗口 resize 结束</td><td>滚动加载、拖拽、按钮连点、埋点上报</td></tr></tbody></table><ol><li>时间戳版：记录 <code>last</code>，每次比较 <code>now - last &gt;= interval</code> 才执行。首次立即执行，但停止触发后<strong>最后一次不执行</strong>。</li><li>定时器版：用 <code>timer</code> 控制，首次不立即执行，但停止后<strong>会补执行最后一次</strong>。</li><li>生产写法通常两者结合，用 <code>leading</code>/<code>trailing</code> 两个开关控制首尾是否执行。</li><li>两者都靠闭包保存 <code>last</code> 或 <code>timer</code>，都属于「状态保持」类应用。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">throttle</span><span class="token punctuation">(</span><span class="token parameter">fn<span class="token punctuation">,</span> interval <span class="token operator">=</span> <span class="token number">300</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> last <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> now <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>now <span class="token operator">-</span> last <span class="token operator">&gt;=</span> interval<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      last <span class="token operator">=</span> now<span class="token punctuation">;</span>
      <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：滚动事件里用防抖会怎样？答：用户持续滚动期间一直不执行，松手才执行一次，页面看起来像卡住了。</li><li>陷阱：只答「防抖是节流的特例」这类含糊说法，面试官会要求你各写一个。</li></ul><h3 id="q14-手写柯里化-curry-它和偏函数有什么区别" tabindex="-1"><a class="header-anchor" href="#q14-手写柯里化-curry-它和偏函数有什么区别" aria-hidden="true">#</a> Q14 手写柯里化（curry），它和偏函数有什么区别？</h3><p><strong>考察点</strong>：考察闭包 + 递归 + 函数 <code>length</code> 属性，同时区分两个易混概念。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：柯里化是把接收多个参数的函数改造成「一次收一部分参数、可连续调用」的函数，靠闭包累积已收到的参数，收齐后执行原函数。</p></blockquote><ol><li>判断收齐的依据是 <code>fn.length</code>（形参个数）。注意它不包含剩余参数和默认值参数，这是最常见的边界坑。</li><li>累积参数靠闭包：每次返回的新函数都记住之前传进来的 <code>args</code>。</li><li>与偏函数（partial）的区别：柯里化是「每次一个参数、链式调用」的严格形式；偏函数是「预先固定一部分参数」，不要求一个一个传，如 <code>Function.prototype.bind</code>。</li><li>实际收益：参数复用、延迟执行（如 <code>bind</code> 出的 <code>add(1)</code> 反复用）、与组合函数（compose）配合做数据处理管道。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">curry</span><span class="token punctuation">(</span><span class="token parameter">fn</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token function">curried</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>args<span class="token punctuation">.</span>length <span class="token operator">&gt;=</span> fn<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>rest</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">curried</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span>args<span class="token punctuation">,</span> <span class="token operator">...</span>rest<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> add <span class="token operator">=</span> <span class="token function">curry</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">a<span class="token punctuation">,</span> b<span class="token punctuation">,</span> c</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> a <span class="token operator">+</span> b <span class="token operator">+</span> c<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">add</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 6</span>
<span class="token function">add</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 6</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：有默认值的参数能用 <code>fn.length</code> 判断吗？答：不能，<code>(a, b = 1) =&gt; {}</code> 的 <code>length</code> 是 1，会提前执行，需要自己约定判断方式。</li><li>陷阱：把柯里化说成「就是 <code>bind</code>」。<code>bind</code> 是偏函数，可以一次固定多个参数。</li></ul><h3 id="q15-什么是模块模式-iife-它解决了什么问题" tabindex="-1"><a class="header-anchor" href="#q15-什么是模块模式-iife-它解决了什么问题" aria-hidden="true">#</a> Q15 什么是模块模式（IIFE）？它解决了什么问题？</h3><p><strong>考察点</strong>：考察闭包在工程上的原始用途——在没有模块系统的年代如何隔离作用域并暴露接口。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：模块模式就是用立即执行函数表达式（IIFE）造一个私有作用域，把状态藏在闭包里，只返回需要暴露的接口，从而避免全局污染并实现封装。</p></blockquote><ol><li>解决的问题一：变量污染全局。IIFE 内部声明的变量不挂到 <code>window</code>，多个文件的同名变量不会互相覆盖。</li><li>解决的问题二：没有封装概念。只返回 <code>{ inc, get }</code>，外部拿不到 <code>count</code> 本身。</li><li>实际写法需要加分号或前置一元运算符（<code>;(function(){})()</code>、<code>!function(){}()</code>），否则前一行没写分号会被当成函数调用。</li><li>现代对照：ES 模块的 <code>export</code> 本身就是模块作用域，顶层变量天然不外泄；模块只会被求值一次，等价于单例。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> counter <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>                       <span class="token comment">// 私有</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span>
    <span class="token function-variable function">inc</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">++</span>count<span class="token punctuation">,</span>
    <span class="token function-variable function">get</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> count<span class="token punctuation">,</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
counter<span class="token punctuation">.</span><span class="token function">inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
counter<span class="token punctuation">.</span>count<span class="token punctuation">;</span>   <span class="token comment">// undefined</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：ES 模块和 IIFE 模块有什么本质区别？答：模块是语言规范的作用域与静态分析（可 tree-shaking），IIFE 只是普通函数调用。</li><li>陷阱：认为 IIFE 能解决循环中 <code>var</code> 的问题——能，但必须把循环变量作为参数传进去，见 Q19。</li></ul><h3 id="q16-手写一个-once-让函数只执行一次-说说它的考察点。" tabindex="-1"><a class="header-anchor" href="#q16-手写一个-once-让函数只执行一次-说说它的考察点。" aria-hidden="true">#</a> Q16 手写一个 <code>once</code>，让函数只执行一次，说说它的考察点。</h3><p><strong>考察点</strong>：考察闭包做状态标记、返回值缓存、<code>this</code> 透传这三个细节是否都想到。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用闭包保存一个 <code>called</code> 标志和首次执行的返回值，之后所有调用都直接返回缓存结果，不再真正执行原函数。</p></blockquote><ol><li>只判断状态还不够：要<strong>缓存首次的返回值</strong>，否则第二次调用返回 <code>undefined</code>，调用方可能踩空。</li><li>要保 <code>this</code> 和参数：用 <code>fn.apply(this, args)</code>，这样它可以直接挂到对象上或做事件回调。</li><li>典型用途：<code>once(document, &#39;DOMContentLoaded&#39;)</code> 类的事件只处理一次、支付/提交按钮防重复、单例初始化（懒加载 SDK）。</li><li>更严谨的并发场景（异步只执行一次）要缓存 Promise 而不是值，让后续调用复用同一个 Promise。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">once</span><span class="token punctuation">(</span><span class="token parameter">fn</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">let</span> called <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token keyword">let</span> result<span class="token punctuation">;</span>
  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>called<span class="token punctuation">)</span> <span class="token punctuation">{</span>
      called <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
      result <span class="token operator">=</span> <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> result<span class="token punctuation">;</span>
  <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：如果原函数抛错了，算执行过吗？答：常见实现里标志已置位，不会再执行；若要可重试，需把置位放在成功之后。</li><li>陷阱：用 <code>fn = null</code> 的方式判断，会覆盖原函数引用，也无法保留返回值，属于典型扣分写法。</li></ul><h3 id="q17-闭包真的会造成内存泄漏吗" tabindex="-1"><a class="header-anchor" href="#q17-闭包真的会造成内存泄漏吗" aria-hidden="true">#</a> Q17 闭包真的会造成内存泄漏吗？</h3><p><strong>考察点</strong>：这是被传播最广的误解之一，考察能否区分「变量被有意保留」和「泄漏」。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：闭包本身不是内存泄漏，它只是延长了变量的生命周期；只有「已经不再需要、却被闭包意外长期持有」时才构成泄漏。</p></blockquote><ol><li>泄漏的定义是：对象已经不再需要，但仍然可达、无法被回收，内存持续增长。闭包保留变量是<strong>有意的设计</strong>，属于特性而非缺陷。</li><li>真正的泄漏场景：挂在 <code>window</code> 上的事件监听一直不摘、<code>setInterval</code> 从不 <code>clearInterval</code>、模块级 Map 缓存只增不删、组件已卸载但回调还引用着大对象/DOM。</li><li>排查方式：Chrome DevTools 的 Memory 面板拍三次堆快照对比，看 <code>Detached HTMLElement</code> 与实例数是否只增不减。</li><li>正确做法：组件卸载时清理监听和定时器；长期缓存用 <code>WeakMap</code>/<code>WeakSet</code>；只把真正需要的字段带进闭包，别顺手引用整个大对象。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 有意保留，不是泄漏</span>
<span class="token keyword">const</span> c <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token keyword">let</span> n <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token operator">++</span>n<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 泄漏：定时器不清理，函数和它引用的 data 永远不会被回收</span>
<span class="token function">setInterval</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">render</span><span class="token punctuation">(</span>bigData<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 IE 时代的泄漏是怎么回事？答：那是旧 JScript 的循环引用问题（DOM 对象与 JS 对象互相引用，引用计数算法回收不了），不是闭包的锅。</li><li>陷阱：面试里说「闭包会导致内存泄漏」，会被追问「那你项目里怎么用闭包」，容易答崩。</li></ul><h3 id="q18-for-var-i-0-i-3-i-settimeout-console-log-i-为什么打印三个-3" tabindex="-1"><a class="header-anchor" href="#q18-for-var-i-0-i-3-i-settimeout-console-log-i-为什么打印三个-3" aria-hidden="true">#</a> Q18 <code>for (var i = 0; i &lt; 3; i++) setTimeout(() =&gt; console.log(i))</code> 为什么打印三个 3？</h3><p><strong>考察点</strong>：把作用域、闭包、事件循环三块知识串起来，是最高频的「陷阱题」。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>var</code> 是函数作用域，整个循环只有一个 <code>i</code>；三个回调都是闭包，捕获的是同一个变量，等它们执行时循环已经结束，<code>i</code> 已经是 3。</p></blockquote><ol><li><code>var i</code> 提升到外层函数（或全局）作用域，循环体里没有任何新作用域，三次迭代共享同一个绑定。</li><li><code>setTimeout</code> 是宏任务，回调要等同步代码全部执行完才排队执行；此时 <code>i</code> 已经循环到 3，所以三次都打印 3。</li><li>关键在于「闭包捕获的是变量本身，不是值的快照」。如果捕获的是值，就不会出现这个问题。</li><li>如果打印语句写在循环体内（不加 <code>setTimeout</code>），则是同步执行，会依次打印 0、1、2。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">var</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 3 3 3</span>
<span class="token punctuation">}</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> j <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> j <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> j<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>j<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 0 1 2</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：如果 <code>delay</code> 不是 0 呢？答：结论一样，仍会全部打印 3，延迟只影响何时打印。</li><li>陷阱：答成「因为 <code>setTimeout</code> 是异步的」就结束。异步只是让执行延后，根因是共享同一个变量。</li></ul><h3 id="q19-循环里-var-输出同一个值-你有哪些修法" tabindex="-1"><a class="header-anchor" href="#q19-循环里-var-输出同一个值-你有哪些修法" aria-hidden="true">#</a> Q19 循环里 <code>var</code> 输出同一个值，你有哪些修法？</h3><p><strong>考察点</strong>：要求给出三种以上可运行的修法，并能说出各自的代价。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：三种主流修法——改用 <code>let</code> 拿每次迭代的独立绑定、用 IIFE 把当次的值作为参数捕获、把值通过 <code>setTimeout</code> 的第三个参数（或 <code>bind</code>）固化到调用参数上。</p></blockquote><ol><li><strong>改用 <code>let</code></strong>：规范规定 <code>for</code> 的 <code>let</code> 每轮迭代都会创建一个新的绑定，并把上一轮的值拷贝过去，闭包各自捕获，最简洁。</li><li><strong>IIFE 捕获</strong>：把当次 <code>i</code> 作为实参传进立即执行函数，函数作用域里有了独立的形参 <code>j</code>，闭包捕获 <code>j</code>。</li><li><strong>传参/<code>bind</code></strong>：<code>setTimeout(fn, 0, i)</code> 把值作为参数传入，或用 <code>fn.bind(null, i)</code>，本质都是把值提前固化。</li><li>选型：新代码一律用 <code>let</code>；老代码里需要兼容 ES5 或要处理异步串行时才用 IIFE。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 1. let：每轮迭代独立绑定</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 2. IIFE：把当次的值作为参数捕获</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">var</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">j</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>j<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// 3. 传参：值固化进调用参数</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">var</span> k <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> k <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> k<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span>console<span class="token punctuation">.</span>log<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> k<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>let</code> 就能解决？答：不是「<code>let</code> 有块级作用域」一句带过，而是每轮迭代生成新绑定并拷贝上一轮的值。</li><li>陷阱：把 <code>var i</code> 改成 <code>let i</code> 就以为万事大吉，但循环里如果还用了 <code>await</code> 和外部共享变量，仍可能有别的时序问题。</li></ul><h3 id="q20-箭头函数和普通函数到底有哪些区别" tabindex="-1"><a class="header-anchor" href="#q20-箭头函数和普通函数到底有哪些区别" aria-hidden="true">#</a> Q20 箭头函数和普通函数到底有哪些区别？</h3><p><strong>考察点</strong>：把 <code>this</code>、构造能力、<code>arguments</code>、原型这几条一起答清，是收束本章 <code>this</code> 部分的题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：箭头函数没有自己的 <code>this</code>、<code>arguments</code>、<code>super</code> 和 <code>prototype</code>，不能当构造函数，<code>this</code> 在定义时就按外层词法作用域固定下来。</p></blockquote><table><thead><tr><th>维度</th><th>普通函数</th><th>箭头函数</th></tr></thead><tbody><tr><td><code>this</code></td><td>调用时决定</td><td>定义时的外层 <code>this</code>，不可改</td></tr><tr><td><code>arguments</code></td><td>有</td><td>无（用剩余参数 <code>...args</code>）</td></tr><tr><td><code>new</code></td><td>可以</td><td>报 TypeError</td></tr><tr><td><code>prototype</code></td><td>有</td><td>没有</td></tr><tr><td><code>call/apply/bind</code> 改 <code>this</code></td><td>有效</td><td>无效（但能传参）</td></tr><tr><td>能否用作生成器</td><td>可以</td><td>不可以</td></tr></tbody></table><ol><li>适用场景：需要固定 <code>this</code> 的回调（<code>setTimeout</code>、数组方法、事件里想用外层 <code>this</code>）。</li><li>不适用场景：对象方法、需要 <code>arguments</code>、需要动态 <code>this</code>、需要当构造函数的场合。</li><li>不适用场景：<code>Vue2</code> 的 <code>methods</code> 里写箭头函数会导致 <code>this</code> 拿不到组件实例（<code>Vue3</code> 组合式 API 里反而推荐）。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：箭头函数能获取外层 <code>arguments</code> 吗？答：能，它沿作用域链找到最近的非箭头函数的 <code>arguments</code>，这也是它被用作包装函数的常见原因。</li><li>陷阱：在对象字面量里写方法用箭头函数，<code>this</code> 会指向外层而不是这个对象，是实际开发中最常见的错误。</li></ul><h3 id="q21-this-到底指向谁-一共几种绑定规则" tabindex="-1"><a class="header-anchor" href="#q21-this-到底指向谁-一共几种绑定规则" aria-hidden="true">#</a> Q21 <code>this</code> 到底指向谁？一共几种绑定规则？</h3><p><strong>考察点</strong>：必答题，要求五种情况一次说全，并能现场判断一段代码。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>this</code> 在函数被调用时确定，看「谁调用的」；一共有五种情况：默认绑定、隐式绑定、显式绑定、<code>new</code> 绑定、箭头函数（词法继承）。</p></blockquote><ol><li><strong>默认绑定</strong>：独立调用 <code>fn()</code>。非严格模式下 <code>this</code> 是 <code>window</code>（Node 里是 <code>globalThis</code>），严格模式下是 <code>undefined</code>。</li><li><strong>隐式绑定</strong>：<code>obj.fn()</code>，<code>this</code> 是调用它的那个对象 <code>obj</code>。只认最后一层，<code>a.b.fn()</code> 的 <code>this</code> 是 <code>b</code>。</li><li><strong>显式绑定</strong>：<code>fn.call(obj)</code>、<code>fn.apply(obj)</code>、<code>fn.bind(obj)</code>，<code>this</code> 被强制指定为 <code>obj</code>。</li><li><strong><code>new</code> 绑定</strong>：<code>new Fn()</code>，<code>this</code> 是新创建的那个实例对象。</li><li><strong>箭头函数</strong>：没有自己的 <code>this</code>，取定义时外层作用域的 <code>this</code>，且 <code>call</code>/<code>apply</code>/<code>bind</code> 都改不了。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：严格模式影响哪一种？答：只影响默认绑定（变 <code>undefined</code>），其余四种不受影响。</li><li>陷阱：用「函数在哪里定义」判断 <code>this</code>。<code>this</code> 只看调用点，这是和变量作用域最大的区别。</li><li>陷阱：忘了 ES 模块和 <code>class</code> 内部默认就是严格模式。</li></ul><h3 id="q22-这几种绑定规则的优先级是怎样的" tabindex="-1"><a class="header-anchor" href="#q22-这几种绑定规则的优先级是怎样的" aria-hidden="true">#</a> Q22 这几种绑定规则的优先级是怎样的？</h3><p><strong>考察点</strong>：考察是否能用一条优先级链处理任意混合写法，而不是死记单个规则。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：优先级从高到低是 <code>new</code> 绑定 &gt; 显式绑定（<code>bind</code>）&gt; 隐式绑定 &gt; 默认绑定；箭头函数不参与排序，直接取外层的 <code>this</code>。</p></blockquote><ol><li><code>new</code> 与 <code>bind</code> 同时出现时，<code>new</code> 胜出：<code>bind</code> 预设的 <code>this</code> 被忽略，但预设的参数仍然生效。</li><li><code>bind</code> 强于隐式绑定：<code>const f = obj.fn.bind(other)</code>，之后 <code>f()</code> 的 <code>this</code> 是 <code>other</code>，再写 <code>obj.f()</code> 也是 <code>other</code>。</li><li><code>bind</code> 之后 <code>call</code>/<code>apply</code> 无法再改动 <code>this</code>，只能传参数，这是一道常见验证题。</li><li>箭头函数优先级不适用：它没有自己的 <code>this</code>，外层是谁就是谁，任何绑定手段都无效。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">Fn</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">const</span> bound <span class="token operator">=</span> <span class="token function">Fn</span><span class="token punctuation">.</span><span class="token function">bind</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;bound&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">bound</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// &#39;bound&#39;</span>
<span class="token keyword">new</span> <span class="token class-name">bound</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// undefined，this 是新实例，bind 的 this 被忽略</span>
<span class="token function">bound</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;call&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;bound&#39;，call 改不动</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>new</code> 一个箭头函数呢？答：直接抛 TypeError，箭头函数没有 <code>[[Construct]]</code>，谈不上优先级。</li><li>陷阱：只背「谁调用指向谁」，遇到 <code>bind</code> 与 <code>new</code> 的组合题就答错。</li></ul><h3 id="q23-箭头函数的-this-是怎么确定的-能用-call-改吗" tabindex="-1"><a class="header-anchor" href="#q23-箭头函数的-this-是怎么确定的-能用-call-改吗" aria-hidden="true">#</a> Q23 箭头函数的 <code>this</code> 是怎么确定的？能用 <code>call</code> 改吗？</h3><p><strong>考察点</strong>：考察「词法 <code>this</code>」的准确表述，以及它与绑定规则的关系。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：箭头函数的 <code>this</code> 在<strong>定义时</strong>就取外层作用域的 <code>this</code>，之后永久固定，<code>call</code>/<code>apply</code>/<code>bind</code> 都改不了，因为它压根没有自己的 <code>this</code>。</p></blockquote><ol><li>规范层面：箭头函数没有 <code>[[ThisMode]]</code> 为 lexical 之外的记录，函数体内出现 <code>this</code> 时直接沿作用域链找外层函数的 <code>this</code>。</li><li>因此「固定 <code>this</code>」的经典写法是 <code>const self = this</code> 或 <code>.bind(this)</code>，改用箭头函数更简洁。</li><li>陷阱点：如果外层也是箭头函数，就继续往外找，一直到最近的非箭头函数或全局；写嵌套箭头时容易算错到底指向谁。</li><li>也正因为如此，箭头函数不能被 <code>new</code>、也没有 <code>prototype</code>，不能作为需要动态 <code>this</code> 的方法。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;obj&#39;</span><span class="token punctuation">,</span>
  <span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;obj&#39;，继承 greet 的 this</span>
    <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// undefined</span>
  <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
obj<span class="token punctuation">.</span><span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>obj.method = () =&gt; console.log(this)</code> 里的 <code>this</code> 是谁？答：定义位置的外层，通常是模块顶层或 <code>window</code>，不是 <code>obj</code>。</li><li>陷阱：说「箭头函数的 <code>this</code> 指向它所在的函数」不够准确，是「定义时外层作用域里的 <code>this</code> 值」。</li></ul><h3 id="q24-为什么箭头函数不能当构造函数-它和-new-的关系是什么" tabindex="-1"><a class="header-anchor" href="#q24-为什么箭头函数不能当构造函数-它和-new-的关系是什么" aria-hidden="true">#</a> Q24 为什么箭头函数不能当构造函数？它和 <code>new</code> 的关系是什么？</h3><p><strong>考察点</strong>：考察对 <code>[[Construct]]</code>、<code>prototype</code> 这些内部机制的理解深度。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：因为箭头函数没有 <code>[[Construct]]</code> 内部方法，也没有 <code>prototype</code> 属性，<code>new</code> 一个箭头函数会直接抛 TypeError。</p></blockquote><ol><li>只有普通函数、方法、<code>class</code> 带 <code>[[Construct]]</code>；箭头函数是「轻量函数」，规范里就没有给它这个方法。</li><li><code>new Fn()</code> 的第二步需要读 <code>Fn.prototype</code> 来设置新对象的原型，而 <code>Fn.prototype</code> 是 <code>undefined</code>，机制上无法成立，所以引擎直接拒绝。</li><li>同理箭头函数没有 <code>super</code> 和 <code>new.target</code> 的绑定，也不能用作生成器函数（<code>function*</code>）。</li><li>面试延伸：这也解释了为什么用箭头函数做组件或工具函数时更省内存——每个箭头函数不额外带一个 <code>prototype</code> 对象。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>class</code> 里的字段写成箭头函数，能不能 <code>new</code>？答：能，<code>new</code> 的是类本身，那个字段只是实例属性。</li><li>陷阱：答「因为箭头函数没有 <code>this</code>」。它有 <code>this</code>，只是没有自己的绑定，这两个说法差别很大。</li></ul><h3 id="q25-对象的方法里-this-为什么会丢-怎么解决" tabindex="-1"><a class="header-anchor" href="#q25-对象的方法里-this-为什么会丢-怎么解决" aria-hidden="true">#</a> Q25 对象的方法里 <code>this</code> 为什么会丢？怎么解决？</h3><p><strong>考察点</strong>：实际开发中最高频的 bug 之一，考察是否理解「<code>this</code> 由调用点决定」。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>this</code> 由调用方式决定，<code>obj.fn()</code> 时是 <code>obj</code>，一旦把方法取出来单独调用（<code>const f = obj.fn; f()</code>），调用点变成独立调用，<code>this</code> 退化为默认绑定（非严格模式 <code>window</code>）。</p></blockquote><ol><li>赋值、作为参数传递、作为回调注册，都会让方法「脱离」原对象，从而丢失 <code>this</code>。</li><li>修法一：<code>bind</code> 固定，<code>const f = obj.fn.bind(obj)</code>，最稳，适合注册事件。</li><li>修法二：包一层箭头函数，<code>setTimeout(() =&gt; obj.fn(), 0)</code>，保留调用点。</li><li>修法三：<code>class</code> 里用箭头函数字段（<code>fn = () =&gt; {}</code>），实例化时就绑到实例上，代价是每个实例各有一份函数。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span>
  <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;obj&#39;</span><span class="token punctuation">,</span>
  <span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> f <span class="token operator">=</span> obj<span class="token punctuation">.</span>getName<span class="token punctuation">;</span>
<span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// TypeError 或 undefined，this 丢了</span>
obj<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                <span class="token comment">// &#39;obj&#39;，正常</span>
<span class="token keyword">const</span> g <span class="token operator">=</span> obj<span class="token punctuation">.</span><span class="token function">getName</span><span class="token punctuation">.</span><span class="token function">bind</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token function">g</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                          <span class="token comment">// &#39;obj&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：React 类组件里为什么要 <code>bind(this)</code>？答：事件回调被取出后调用，<code>this</code> 丢失，拿不到实例，所以构造器里 bind 或写成箭头函数字段。</li><li>陷阱：说「<code>this</code> 指向定义它的对象」。<code>this</code> 与定义位置无关，只与调用点有关。</li></ul><h3 id="q26-事件回调里的-this-指向谁-箭头函数有什么不同" tabindex="-1"><a class="header-anchor" href="#q26-事件回调里的-this-指向谁-箭头函数有什么不同" aria-hidden="true">#</a> Q26 事件回调里的 <code>this</code> 指向谁？箭头函数有什么不同？</h3><p><strong>考察点</strong>：考察 DOM 事件模型与 <code>this</code> 的结合，常常追问事件委托。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用普通函数注册的事件回调，<code>this</code> 指向绑定事件的元素（即 <code>currentTarget</code>）；用箭头函数则取外层作用域的 <code>this</code>，与元素无关。</p></blockquote><ol><li>原因：<code>addEventListener</code> 内部以元素作为 <code>this</code> 调用回调（等价于 <code>handler.call(element, event)</code>），这是一次隐式绑定。</li><li><code>this === e.currentTarget</code> 成立；注意不要把 <code>this</code> 当成 <code>e.target</code>——事件委托时 <code>target</code> 是真正触发的最内层元素，<code>currentTarget</code> 才是绑定的元素。</li><li>箭头函数写法：<code>el.addEventListener(&#39;click&#39;, () =&gt; this.handle())</code>，<code>this</code> 来自外层，Vue/React 组件里常用来访问组件实例。</li><li>移除监听的坑：<code>removeEventListener</code> 必须传<strong>同一个函数引用</strong>，所以用 <code>bind</code> 或箭头函数时要把引用存下来，否则移除不掉。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> btn <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;#btn&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
btn<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">this</span> <span class="token operator">===</span> e<span class="token punctuation">.</span>currentTarget<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
btn<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                     <span class="token comment">// 外层 this（模块里常是 undefined）</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：事件委托里怎么定位到具体子项？答：用 <code>e.target.closest(&#39;.item&#39;)</code>，结合 <code>currentTarget</code> 判断范围。</li><li>陷阱：<code>el.onclick = fn</code> 与 <code>addEventListener</code> 的 <code>this</code> 一样都是元素，但前者会覆盖已有监听，且无法设置捕获与 <code>once</code>。</li></ul><h3 id="q27-settimeout-里的-this-是什么-为什么和想象的不一样" tabindex="-1"><a class="header-anchor" href="#q27-settimeout-里的-this-是什么-为什么和想象的不一样" aria-hidden="true">#</a> Q27 <code>setTimeout</code> 里的 <code>this</code> 是什么？为什么和想象的不一样？</h3><p><strong>考察点</strong>：考察宿主环境调用回调的方式，是「<code>this</code> 丢失」的另一典型场景。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：浏览器里传给 <code>setTimeout</code> 的普通函数回调，<code>this</code> 默认是 <code>window</code>（Node 里是 <code>Timeout</code> 对象），因为宿主是「直接调用」回调，没有绑定任何调用者。</p></blockquote><ol><li>这不是 <code>setTimeout</code> 做了什么特殊处理，而是标准的默认绑定：宿主调用时没提供调用者，非严格模式下 <code>this</code> 被包装成全局对象。</li><li>所以 <code>setTimeout(obj.method, 100)</code> 里的 <code>this</code> 不是 <code>obj</code>，对象方法在定时器里必然丢 <code>this</code>——这是最经典的坑。</li><li>三种修法：<code>setTimeout(obj.method.bind(obj), 100)</code>、<code>setTimeout(() =&gt; obj.method(), 100)</code>、把方法改成箭头函数字段。</li><li>补充：<code>setTimeout</code> 的第三个及以后的参数会作为回调实参传入，<code>setTimeout(fn, 0, a, b)</code> 等价于调用 <code>fn(a, b)</code>，这是低成本的传参技巧。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么定时器最少延迟是 4ms？答：嵌套超过 5 层的定时器会被规范强制最小 4ms，属于浏览器的节流策略。</li><li>陷阱：说「<code>setTimeout</code> 的 <code>this</code> 指向定时器对象」。那是 Node 的 <code>Timeout</code> 实例，浏览器里是全局对象。</li></ul><h3 id="q28-call、apply、bind-有什么区别" tabindex="-1"><a class="header-anchor" href="#q28-call、apply、bind-有什么区别" aria-hidden="true">#</a> Q28 <code>call</code>、<code>apply</code>、<code>bind</code> 有什么区别？</h3><p><strong>考察点</strong>：基础必答，要求说清「是否立即执行」和「参数形式」两条差异，并能提到 <code>bind</code> 的偏函数能力。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：三者都用来指定 <code>this</code>；<code>call</code>/<code>apply</code> 立即执行（参数分别是列表和数组），<code>bind</code> 不执行、返回一个永久绑定了 <code>this</code> 的新函数。</p></blockquote><table><thead><tr><th>方法</th><th>是否立即执行</th><th>参数形式</th><th>返回值</th></tr></thead><tbody><tr><td><code>call</code></td><td>是</td><td><code>fn.call(thisArg, a, b)</code></td><td>原函数返回值</td></tr><tr><td><code>apply</code></td><td>是</td><td><code>fn.apply(thisArg, [a, b])</code></td><td>原函数返回值</td></tr><tr><td><code>bind</code></td><td>否</td><td><code>fn.bind(thisArg, a, b)</code></td><td>绑好 <code>this</code> 的新函数</td></tr></tbody></table><ol><li>记忆点：<code>apply</code> 的 <code>a</code> 对应 array（数组），<code>call</code> 对应逗号分隔列表。</li><li><code>bind</code> 的额外能力是偏函数：<code>add.bind(null, 1)(2)</code> 先把 <code>1</code> 固定住，后续调用只传剩下的参数。</li><li>选择场景：<code>Math.max.apply(null, arr)</code> 现在可以用 <code>Math.max(...arr)</code> 替代；需要把函数和上下文一起传递时用 <code>bind</code>。</li><li>注意：<code>bind</code> 的 <code>this</code> 无法被后续 <code>call</code>/<code>apply</code> 覆盖，但 <code>new</code> 调用时 <code>bind</code> 的 <code>this</code> 会被忽略。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>bind</code> 是深绑定吗？答：不是，它只固定第一层函数的 <code>this</code>；返回的新函数再被当作方法调用也不会改。</li><li>陷阱：说「<code>bind</code> 也立即执行」。它只返回新函数，这是最常被追问的一点。</li></ul><h3 id="q29-手写-call-和-apply-说说关键细节。" tabindex="-1"><a class="header-anchor" href="#q29-手写-call-和-apply-说说关键细节。" aria-hidden="true">#</a> Q29 手写 <code>call</code> 和 <code>apply</code>，说说关键细节。</h3><p><strong>考察点</strong>：手写题，考察临时属性挂载、<code>Symbol</code> 防冲突、<code>null</code> 与原始值处理。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：核心思路是「把函数临时挂到目标对象上，用对象方法调用的方式借它的 <code>this</code>，执行完立刻删除」。</p></blockquote><ol><li>临时键必须用 <code>Symbol</code>，否则可能覆盖对象上的同名属性（比如对象本来就有 <code>fn</code> 字段）。</li><li><code>ctx</code> 为 <code>null</code>/<code>undefined</code> 时要替换成 <code>globalThis</code>（严格模式下是原值，但手写版通常做非严格语义）；传原始值时要用 <code>Object()</code> 包装，否则挂属性会静默失败。</li><li>执行后必须 <code>delete</code>，并且用 <code>try/finally</code> 兜底，避免函数抛错留下脏属性。</li><li>这是「隐式绑定」的实际应用：<code>ctx[key]()</code> 时 <code>this</code> 就是 <code>ctx</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token class-name">Function</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">myCall</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">ctx<span class="token punctuation">,</span> <span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  ctx <span class="token operator">=</span> ctx <span class="token operator">==</span> <span class="token keyword">null</span> <span class="token operator">?</span> globalThis <span class="token operator">:</span> <span class="token function">Object</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 处理 null 与原始值</span>
  <span class="token keyword">const</span> key <span class="token operator">=</span> <span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token string">&#39;fn&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                       <span class="token comment">// Symbol 避免键名冲突</span>
  ctx<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">;</span>
  <span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> ctx<span class="token punctuation">[</span>key<span class="token punctuation">]</span><span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span> <span class="token keyword">finally</span> <span class="token punctuation">{</span>
    <span class="token keyword">delete</span> ctx<span class="token punctuation">[</span>key<span class="token punctuation">]</span><span class="token punctuation">;</span>                              <span class="token comment">// 无论成功失败都清理</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token class-name">Function</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">myApply</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">ctx<span class="token punctuation">,</span> args <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">myCall</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token operator">...</span>args<span class="token punctuation">)</span><span class="token punctuation">;</span>               <span class="token comment">// apply 只是参数形式不同</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不能定义成箭头函数？答：箭头函数没有自己的 <code>this</code>，拿不到 <code>this</code>（即被调用的原函数）。</li><li>陷阱：用字符串 <code>&#39;fn&#39;</code> 当临时键；或者忘了 <code>delete</code>，会在对象上留下一个属性。</li></ul><h3 id="q30-手写-bind-为什么要考虑-new-的情况" tabindex="-1"><a class="header-anchor" href="#q30-手写-bind-为什么要考虑-new-的情况" aria-hidden="true">#</a> Q30 手写 <code>bind</code>，为什么要考虑 <code>new</code> 的情况？</h3><p><strong>考察点</strong>：深挖题，考察 <code>new</code> 优先级高于 <code>bind</code> 这条规则的实现方式。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>bind</code> 返回一个闭包，调用时用 <code>apply</code> 把预设的 <code>this</code> 和合并后的参数传给原函数；但被 <code>new</code> 调用时必须忽略预设的 <code>this</code>，让实例成为 <code>this</code>。</p></blockquote><ol><li>参数合并：预设参数在前、调用时参数在后，这正是偏函数的实现。</li><li>判断是否被 <code>new</code> 调用：用 <code>new.target</code> 最准确（<code>this instanceof bound</code> 在原型被改写后不可靠）。</li><li>被 <code>new</code> 时还要让实例能沿着原函数的原型链查找，所以把 <code>bound.prototype</code> 指向 <code>Object.create(fn.prototype)</code>。</li><li>返回值规则沿用构造函数那套：<code>new bound()</code> 时如果原函数返回对象就用那个对象，否则用新建的实例。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token class-name">Function</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">myBind</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">ctx<span class="token punctuation">,</span> <span class="token operator">...</span>preset</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> fn <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">;</span>
  <span class="token keyword">function</span> <span class="token function">bound</span><span class="token punctuation">(</span><span class="token parameter"><span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// new.target 有值说明是 new 调用，此时 this 就是新实例</span>
    <span class="token keyword">const</span> self <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">.</span>target <span class="token operator">?</span> <span class="token keyword">this</span> <span class="token operator">:</span> <span class="token punctuation">(</span>ctx <span class="token operator">==</span> <span class="token keyword">null</span> <span class="token operator">?</span> globalThis <span class="token operator">:</span> <span class="token function">Object</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token function">fn</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span>preset<span class="token punctuation">,</span> <span class="token operator">...</span>args<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>fn<span class="token punctuation">.</span>prototype<span class="token punctuation">)</span> bound<span class="token punctuation">.</span>prototype <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span>fn<span class="token punctuation">.</span>prototype<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> bound<span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>bind</code> 之后再 <code>call</code> 改不了 <code>this</code>？答：<code>bound</code> 内部写死了 <code>ctx</code>，外层传入的 <code>thisArg</code> 被完全忽略。</li><li>陷阱：用 <code>this instanceof bound</code> 判断 <code>new</code>，一旦 <code>bound.prototype</code> 指向了 <code>fn.prototype</code>，判断就失真。</li></ul><h3 id="q31-new-一个对象的时候-引擎到底做了哪几件事" tabindex="-1"><a class="header-anchor" href="#q31-new-一个对象的时候-引擎到底做了哪几件事" aria-hidden="true">#</a> Q31 <code>new</code> 一个对象的时候，引擎到底做了哪几件事？</h3><p><strong>考察点</strong>：原型链和构造函数的总入口，要求按四步准确复述。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>new</code> 做四件事：创建新对象、把它的原型指向构造函数的 <code>prototype</code>、以它为 <code>this</code> 执行构造函数、按返回值规则决定最终返回谁。</p></blockquote><ol><li>新建一个空的普通对象。</li><li>把新对象的 <code>[[Prototype]]</code> 指向 <code>Fn.prototype</code>，这样实例才能访问原型上的方法。</li><li>以新对象为 <code>this</code> 执行构造函数函数体，实例属性在这一步挂到对象上。</li><li>如果构造函数返回的是对象（含数组、函数），就返回那个对象；否则返回第 1 步创建的新对象。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">Person</span><span class="token punctuation">(</span><span class="token parameter">name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name <span class="token operator">=</span> name<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token class-name">Person</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">say</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> p <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token string">&#39;刘群&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>p<span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token class-name">Person</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span> <span class="token comment">// true</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>new</code> 出来的对象怎么找到构造函数的？答：沿原型链找到 <code>Person.prototype</code>，再读它的 <code>constructor</code>。</li><li>陷阱：说「<code>new</code> 就是把 <code>this</code> 指向函数本身」。指向的是新建的实例对象，不是函数。</li></ul><h3 id="q32-构造函数里-return-一个值-会发生什么" tabindex="-1"><a class="header-anchor" href="#q32-构造函数里-return-一个值-会发生什么" aria-hidden="true">#</a> Q32 构造函数里 <code>return</code> 一个值，会发生什么？</h3><p><strong>考察点</strong>：考察 <code>new</code> 第四步的返回值规则，是容易漏的细节题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：构造函数返回<strong>原始值</strong>（数字、字符串、布尔、<code>null</code>、<code>undefined</code>）时被忽略，仍然返回新实例；返回<strong>对象或函数</strong>时，该对象会替换掉新实例成为 <code>new</code> 的结果。</p></blockquote><ol><li>原因：<code>[[Construct]]</code> 规定，只有返回值的类型是 Object 才采用它，否则一律返回内部创建的 <code>this</code>。</li><li>常见影响：想通过 <code>return {}</code> 破坏单例或提前结束构造，结果 <code>instanceof</code> 判断失效，因为返回的已经不是这个类的实例。</li><li>这条规则对 <code>class</code> 同样适用，但派生类（<code>extends</code>）构造函数更严格：只能返回对象或 <code>undefined</code>，返回原始值或 <code>null</code> 都会抛 TypeError；基类则与普通函数一致，返回原始值被忽略。</li><li>与普通函数调用的区别：直接调用 <code>Person()</code> 时返回什么就是什么，没有这层「对象优先」的规则。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token constant">A</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token number">42</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>        <span class="token comment">// 返回原始值 → 被忽略</span>
<span class="token keyword">new</span> <span class="token class-name">A</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                        <span class="token comment">// A { x: 1 }</span>

<span class="token keyword">function</span> <span class="token constant">B</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>   <span class="token comment">// 返回对象 → 生效</span>
<span class="token keyword">new</span> <span class="token class-name">B</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                                        <span class="token comment">// { y: 2 }，不是 B 的实例</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>return null</code> 呢？答：<code>null</code> 的 <code>typeof</code> 是 <code>&#39;object&#39;</code>，但它是原始值，规则里按「非对象」处理，返回新实例。</li><li>陷阱：以为 <code>return []</code> 也会被忽略——数组是对象，会生效。</li></ul><h3 id="q33-手写一个-new-并解释它和-object-create-的关系。" tabindex="-1"><a class="header-anchor" href="#q33-手写一个-new-并解释它和-object-create-的关系。" aria-hidden="true">#</a> Q33 手写一个 <code>new</code>，并解释它和 <code>Object.create</code> 的关系。</h3><p><strong>考察点</strong>：手写题，同时考察对原型设置的两种写法的理解。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用 <code>Object.create(Ctor.prototype)</code> 造出带正确原型的对象，<code>apply</code> 执行构造函数，再按返回值规则决定返回谁。</p></blockquote><ol><li><code>Object.create(Ctor.prototype)</code> 等价于旧写法 <code>obj.__proto__ = Ctor.prototype</code>，但它是标准 API、性能可控、不触发 <code>setPrototypeOf</code> 的优化破坏。</li><li>用 <code>apply</code> 而不是 <code>call</code>，因为参数是数组形式。</li><li>返回值判断要覆盖函数：<code>typeof ret === &#39;function&#39;</code> 时也属于对象分支。</li><li>补一句 <code>Object.create</code> 的实质：创建一个空对象并指定它的 <code>[[Prototype]]</code>，第二个参数可定义属性描述符。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">myNew</span><span class="token punctuation">(</span><span class="token parameter">Ctor<span class="token punctuation">,</span> <span class="token operator">...</span>args</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> Ctor <span class="token operator">!==</span> <span class="token string">&#39;function&#39;</span><span class="token punctuation">)</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">TypeError</span><span class="token punctuation">(</span><span class="token string">&#39;Ctor is not a constructor&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> obj <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">Ctor</span><span class="token punctuation">.</span>prototype<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 1、2 步：创建对象并设置原型</span>
  <span class="token keyword">const</span> ret <span class="token operator">=</span> <span class="token function">Ctor</span><span class="token punctuation">.</span><span class="token function">apply</span><span class="token punctuation">(</span>obj<span class="token punctuation">,</span> args<span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 3 步：以 obj 为 this 执行</span>
  <span class="token keyword">const</span> isObj <span class="token operator">=</span> ret <span class="token operator">!==</span> <span class="token keyword">null</span> <span class="token operator">&amp;&amp;</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> ret <span class="token operator">===</span> <span class="token string">&#39;object&#39;</span> <span class="token operator">||</span> <span class="token keyword">typeof</span> ret <span class="token operator">===</span> <span class="token string">&#39;function&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> isObj <span class="token operator">?</span> ret <span class="token operator">:</span> obj<span class="token punctuation">;</span>                    <span class="token comment">// 4 步：返回值规则</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>class</code> 能用这个 <code>myNew</code> 创建吗？答：不能，<code>class</code> 必须用 <code>new</code> 或 <code>Reflect.construct</code>，直接 <code>apply</code> 会抛 TypeError。</li><li>陷阱：忘了判断 <code>ret !== null</code>，<code>return null</code> 时会被错误地当成对象返回。</li></ul><h3 id="q34-prototype、-proto-、constructor-这三者的关系是什么" tabindex="-1"><a class="header-anchor" href="#q34-prototype、-proto-、constructor-这三者的关系是什么" aria-hidden="true">#</a> Q34 <code>prototype</code>、<code>__proto__</code>、<code>constructor</code> 这三者的关系是什么？</h3><p><strong>考察点</strong>：原型部分的必答题，要求能画三角关系并说清每个属性挂在哪。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：函数有 <code>prototype</code> 属性（指向原型对象），对象有 <code>[[Prototype]]</code>（<code>__proto__</code> 是它的访问器）指向自己的原型；原型对象上的 <code>constructor</code> 又指回构造函数。</p></blockquote><ol><li><code>Person.prototype</code> 是函数才有的属性，它是一个普通对象，会被实例共享。</li><li><code>p.__proto__</code> 实际读的是 <code>Object.prototype</code> 上的访问器，最终得到 <code>[[Prototype]]</code>；规范推荐用 <code>Object.getPrototypeOf(p)</code>。</li><li><code>Person.prototype.constructor === Person</code>，这是为了让实例能反查构造函数；但手动改写 <code>prototype</code> 会丢掉它，需要补回来。</li><li>狐狸尾巴：<code>__proto__</code> 只是历史兼容的访问器，<code>Object.create(null)</code> 出来的对象没有它。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">Person</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token keyword">const</span> p <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Person</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
p<span class="token punctuation">.</span>__proto__ <span class="token operator">===</span> <span class="token class-name">Person</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span>              <span class="token comment">// true</span>
<span class="token class-name">Person</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span>constructor <span class="token operator">===</span> Person<span class="token punctuation">;</span>       <span class="token comment">// true</span>
<span class="token class-name">Person</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span>__proto__ <span class="token operator">===</span> <span class="token class-name">Object</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span> <span class="token comment">// true</span>
Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>Person<span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token class-name">Function</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span> <span class="token comment">// true，函数也是对象</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>p.constructor</code> 是从哪来的？答：<code>p</code> 自己没有，沿原型链在 <code>Person.prototype</code> 上找到。</li><li>陷阱：把 <code>__proto__</code> 当成标准属性写进代码。生产代码用 <code>Object.getPrototypeOf</code> / <code>Object.setPrototypeOf</code>。</li></ul><h3 id="q35-原型链是怎么查找属性的-终点在哪里" tabindex="-1"><a class="header-anchor" href="#q35-原型链是怎么查找属性的-终点在哪里" aria-hidden="true">#</a> Q35 原型链是怎么查找属性的？终点在哪里？</h3><p><strong>考察点</strong>：考察查找过程和「终点是 <code>null</code>」，以及属性遮蔽。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：访问 <code>obj.x</code> 时先看自身属性，没有就沿 <code>[[Prototype]]</code> 逐级向上找，直到 <code>Object.prototype</code>，再往上 <code>[[Prototype]]</code> 是 <code>null</code>，此时返回 <code>undefined</code>。</p></blockquote><ol><li>查找顺序：自身 → 原型 → 原型的原型 → … → <code>Object.prototype</code> → <code>null</code>。</li><li>终点明确：<code>Object.prototype.__proto__ === null</code>，这是所有普通对象原型链的尽头。</li><li>属性遮蔽（shadowing）：实例上写了同名属性，原型上的就访问不到，但原型上的值仍然存在。</li><li>用途上，原型链实现了方法共享（方法只存一份）与继承；代价是查找是线性的，链太长会拖慢访问，也可能被原型污染攻击影响。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> arr <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token comment">// arr → Array.prototype → Object.prototype → null</span>
arr<span class="token punctuation">.</span><span class="token function">hasOwnProperty</span><span class="token punctuation">(</span><span class="token string">&#39;length&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true，自身属性</span>
arr<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                  <span class="token comment">// 来自 Array.prototype</span>
arr<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>               <span class="token comment">// 来自 Array.prototype（先于 Object.prototype 命中）</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么只判断自身属性？答：<code>Object.hasOwn(obj, &#39;x&#39;)</code>（ES2022），旧写法 <code>Object.prototype.hasOwnProperty.call(obj, &#39;x&#39;)</code>。</li><li>陷阱：说原型链终点是 <code>Object.prototype</code>，漏掉最后指向 <code>null</code> 这一步。</li></ul><h3 id="q36-instanceof-的原理是什么-它有哪些局限" tabindex="-1"><a class="header-anchor" href="#q36-instanceof-的原理是什么-它有哪些局限" aria-hidden="true">#</a> Q36 <code>instanceof</code> 的原理是什么？它有哪些局限？</h3><p><strong>考察点</strong>：考察原理与失效场景，是「会用」和「用对」的分水岭。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>a instanceof B</code> 就是沿 <code>a</code> 的原型链查找，看是否出现 <code>B.prototype</code>；它只看原型链、不做类型推断，所以在跨窗口、原始值、原型被改的场景下会失效。</p></blockquote><ol><li>原理：取 <code>B.prototype</code>，从 <code>Object.getPrototypeOf(a)</code> 开始逐级向上比较，命中就 <code>true</code>，到 <code>null</code> 就 <code>false</code>。</li><li>局限一：原始值永远为 <code>false</code>，<code>1 instanceof Number</code> 是 <code>false</code>，因为原始值没有原型链。</li><li>局限二：跨 <code>realm</code>（iframe、Node 的 <code>vm</code>）失效，两边各有自己的 <code>Array.prototype</code>，判断不出来。</li><li>局限三：原型可被改写，<code>Object.setPrototypeOf</code> 或改 <code>prototype</code> 之后结果不可信；<code>Object.create(null)</code> 的对象 <code>instanceof Object</code> 也是 <code>false</code>。</li><li>补充：<code>Symbol.hasInstance</code> 可以自定义 <code>instanceof</code> 的行为，<code>Array.isArray</code> 这类内置方法比它更可靠。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：跨 iframe 怎么判断数组？答：用 <code>Array.isArray</code>，它按内部槽 <code>[[Class]]</code> 判断，不受 realm 影响。</li><li>陷阱：把 <code>instanceof</code> 当成「类型检测」。它检测的是原型链，不是类型。</li></ul><h3 id="q37-手写一个-instanceof。" tabindex="-1"><a class="header-anchor" href="#q37-手写一个-instanceof。" aria-hidden="true">#</a> Q37 手写一个 <code>instanceof</code>。</h3><p><strong>考察点</strong>：手写题，考察边界处理（原始值、<code>null</code>）和原型链遍历。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：先排除非对象，再取构造函数的 <code>prototype</code>，从对象的原型开始循环比较，到 <code>null</code> 结束。</p></blockquote><ol><li>边界一：<code>null</code> 和 <code>undefined</code> 直接返回 <code>false</code>，因为 <code>Object.getPrototypeOf(null)</code> 会抛错。</li><li>边界二：原始值返回 <code>false</code>，只有对象和函数才有原型链。</li><li>用 <code>Object.getPrototypeOf</code> 而不是 <code>__proto__</code>，避免依赖访问器。</li><li>如果要和原生行为对齐，还要先判断 <code>Ctor[Symbol.hasInstance]</code>，原生 <code>instanceof</code> 会优先走这个钩子。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">myInstanceof</span><span class="token punctuation">(</span><span class="token parameter">obj<span class="token punctuation">,</span> Ctor</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>obj <span class="token operator">===</span> <span class="token keyword">null</span> <span class="token operator">||</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> obj <span class="token operator">!==</span> <span class="token string">&#39;object&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token keyword">typeof</span> obj <span class="token operator">!==</span> <span class="token string">&#39;function&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> target <span class="token operator">=</span> <span class="token class-name">Ctor</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span>
  <span class="token keyword">let</span> cur <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">while</span> <span class="token punctuation">(</span>cur <span class="token operator">!==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>cur <span class="token operator">===</span> target<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    cur <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>cur<span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token function">myInstanceof</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> Array<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// true</span>
<span class="token function">myInstanceof</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> Number<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// false，与原生一致</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>myInstanceof(Object.create(null), Object)</code> 返回什么？答：<code>false</code>，它的原型链是空的。</li><li>陷阱：循环写成 <code>while (cur)</code>，虽然 <code>null</code> 会退出，但漏掉「原始值先排除」这一步就会在 <code>Object.getPrototypeOf(1)</code> 上出错（会返回 <code>Number.prototype</code>，与原生语义不符）。</li></ul><h3 id="q38-object-create-null-有什么用-和-有什么区别" tabindex="-1"><a class="header-anchor" href="#q38-object-create-null-有什么用-和-有什么区别" aria-hidden="true">#</a> Q38 <code>Object.create(null)</code> 有什么用？和 <code>{}</code> 有什么区别？</h3><p><strong>考察点</strong>：考察对「无原型对象」的实际价值的理解，常用于字典与缓存场景。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>Object.create(null)</code> 创建一个没有原型的「纯对象」，没有任何继承来的方法，最适合当字典或缓存用，可以从根上避免原型污染和键名冲突。</p></blockquote><ol><li>区别一：<code>{}</code> 的原型是 <code>Object.prototype</code>，所以 <code>obj.toString</code>、<code>obj.constructor</code> 都存在；无原型对象这些全是 <code>undefined</code>。</li><li>区别二：安全性。普通对象上写 <code>obj[&#39;__proto__&#39;]</code> 会走访问器产生副作用；用无原型对象存外部输入的 key，不会被 <code>__proto__</code>、<code>constructor</code> 这类键污染原型。</li><li>区别三：使用成本。它没有 <code>hasOwnProperty</code>，要写 <code>Object.prototype.hasOwnProperty.call(obj, k)</code> 或 <code>Object.hasOwn(obj, k)</code>。</li><li>使用建议：纯粹当 Map 用且键是字符串时选它；需要键是任意类型、需要 <code>size</code>/顺序，就用 <code>Map</code>。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> dict <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
dict<span class="token punctuation">.</span>toString <span class="token operator">=</span> <span class="token string">&#39;value&#39;</span><span class="token punctuation">;</span>       <span class="token comment">// 安全，不会踩到 Object.prototype</span>
dict<span class="token punctuation">.</span>__proto__<span class="token punctuation">;</span>                <span class="token comment">// undefined，没有原型访问器</span>

<span class="token keyword">const</span> plain <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
plain<span class="token punctuation">[</span><span class="token string">&#39;__proto__&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">hacked</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// 走的是访问器，改写的是 plain 自己的原型，风险点</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：它和 <code>Map</code> 怎么选？答：Map 键可以是对象且可迭代、有 <code>size</code>；无原型对象更轻，<code>JSON.parse</code> 后的对象可直接用。</li><li>陷阱：以为 <code>JSON.parse(&#39;{}&#39;)</code> 得到的是无原型对象——它的原型仍是 <code>Object.prototype</code>。</li></ul><h3 id="q39-原型链继承有什么问题" tabindex="-1"><a class="header-anchor" href="#q39-原型链继承有什么问题" aria-hidden="true">#</a> Q39 原型链继承有什么问题？</h3><p><strong>考察点</strong>：继承演进的第一站，考察能否准确指出两个经典缺陷。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：原型链继承的两个致命问题：父类的引用类型属性会被所有子类实例共享；创建子类实例时无法向父类构造函数传参。</p></blockquote><ol><li>共享问题：<code>Child.prototype = new Parent()</code> 时，父类构造函数只执行了一次，原型上的数组/对象属性被所有实例共用，一个实例 <code>push</code> 会影响其他实例。</li><li>传参问题：实例属性本应在构造时按参数初始化，但原型上的属性在 <code>new Parent()</code> 那一刻就固定了，无法针对每个子类实例赋值。</li><li>另一个小问题：直接赋值会丢掉 <code>Child.prototype.constructor</code> 的指向，需要手动补回。</li><li>本质原因：原型是共享的，而实例属性应当是私有的——用原型承载数据就注定共享。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">Parent</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>list <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">function</span> <span class="token function">Child</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token class-name">Child</span><span class="token punctuation">.</span>prototype <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Parent</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// 原型链继承</span>
<span class="token keyword">const</span> a <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Child</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> b <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Child</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
a<span class="token punctuation">.</span>list<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
b<span class="token punctuation">.</span>list<span class="token punctuation">;</span>   <span class="token comment">// [1, 2, 3]，被共享了</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：如果父类的属性都是原始值呢？答：原始值在原型上被改写时会在实例上新建自己的属性，不像引用类型那样互相影响，所以问题主要出在引用类型。</li><li>陷阱：只答「不能传参」，漏掉引用共享，面试官会继续追问。</li></ul><h3 id="q40-说说继承的演进-组合继承、寄生组合继承分别解决了什么问题" tabindex="-1"><a class="header-anchor" href="#q40-说说继承的演进-组合继承、寄生组合继承分别解决了什么问题" aria-hidden="true">#</a> Q40 说说继承的演进：组合继承、寄生组合继承分别解决了什么问题？</h3><p><strong>考察点</strong>：深挖题，考察能否把四种继承方式讲成一条因果链。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：构造函数继承解决引用共享与传参、但方法无法复用；组合继承两者都用、却调用了两次父类构造函数；寄生组合继承用 <code>Object.create</code> 替代 <code>new Parent()</code>，只调用一次且原型干净，是 ES5 的最佳实践。</p></blockquote><table><thead><tr><th>方式</th><th>做法</th><th>解决的问题</th><th>遗留问题</th></tr></thead><tbody><tr><td>原型链继承</td><td><code>Child.prototype = new Parent()</code></td><td>复用原型方法</td><td>引用共享、不能传参</td></tr><tr><td>构造函数继承</td><td>子类里 <code>Parent.call(this, ...)</code></td><td>属性私有、可传参</td><td>方法不能复用，拿不到父类原型方法</td></tr><tr><td>组合继承</td><td>上面两者都用</td><td>兼顾两者</td><td>父类构造函数执行两次，原型上多一份冗余属性</td></tr><tr><td>寄生组合继承</td><td><code>Object.create(Parent.prototype)</code> + <code>Parent.call(this)</code></td><td>只执行一次父类构造，原型干净</td><td>写法稍长，可以直接用 <code>class</code></td></tr></tbody></table><ol><li>演进主线：先要方法共享 → 原型链继承，发现引用共享和不能传参 → 加构造函数继承补上实例属性 → 组合继承兼顾两者却调了两次父类 → 寄生组合继承用 <code>Object.create</code> 去掉那次多余的调用。</li><li>三个判断标准：父类构造函数被执行了几次、子类原型上有没有多余的属性和方法、<code>constructor</code> 有没有指回子类自身。</li><li>工程建议：现代项目直接用 <code>class extends</code>，它编译后的产物就是寄生组合继承；只有维护 ES5 老代码或需要手写继承时才纠结这几种写法。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">function</span> <span class="token function">Parent</span><span class="token punctuation">(</span><span class="token parameter">name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name <span class="token operator">=</span> name<span class="token punctuation">;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>list <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token class-name">Parent</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">say</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function">Child</span><span class="token punctuation">(</span><span class="token parameter">name<span class="token punctuation">,</span> age</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">Parent</span><span class="token punctuation">.</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> name<span class="token punctuation">)</span><span class="token punctuation">;</span>                        <span class="token comment">// 1. 继承实例属性，可传参</span>
  <span class="token keyword">this</span><span class="token punctuation">.</span>age <span class="token operator">=</span> age<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token class-name">Child</span><span class="token punctuation">.</span>prototype <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token class-name">Parent</span><span class="token punctuation">.</span>prototype<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 2. 继承原型方法，不执行父类构造函数</span>
<span class="token class-name">Child</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span>constructor <span class="token operator">=</span> Child<span class="token punctuation">;</span>               <span class="token comment">// 3. 修正 constructor 指向</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：Babel 编译 <code>class extends</code> 产物长什么样？答：就是寄生组合继承加 <code>Object.setPrototypeOf(Child, Parent)</code> 与 <code>_inherits</code> 辅助函数。</li><li>陷阱：说组合继承是最终答案。它多执行了一次父类构造函数，是个已知的浪费。</li></ul><h3 id="q41-class-extends-的本质是什么" tabindex="-1"><a class="header-anchor" href="#q41-class-extends-的本质是什么" aria-hidden="true">#</a> Q41 <code>class extends</code> 的本质是什么？</h3><p><strong>考察点</strong>：深挖题，考察是否知道 <code>class</code> 只是原型的语法糖，但比 ES5 继承多了一条构造器链。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>class extends</code> 本质仍是原型继承，但多了一条关键的构造器链：子类构造函数的 <code>[[Prototype]]</code> 指向父类构造函数，所以静态属性和静态方法也能被继承。</p></blockquote><ol><li>实例链：<code>Child.prototype.__proto__ === Parent.prototype</code>，来自 <code>extends</code> 自动建立的设置。</li><li>构造器链：<code>Object.getPrototypeOf(Child) === Parent</code>，这是 ES5 寄生组合继承里容易漏掉的一条，也是静态成员继承的来源。</li><li><code>class</code> 内部默认严格模式，且必须用 <code>new</code> 调用，不能像函数那样直接调用。</li><li>子类构造函数里必须先 <code>super()</code> 才能使用 <code>this</code>，因为实例是由父类构造函数创建的，<code>super</code> 之前 <code>this</code> 还没绑定（TDZ 行为）。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">class</span> <span class="token class-name">Parent</span> <span class="token punctuation">{</span> <span class="token keyword">static</span> tag <span class="token operator">=</span> <span class="token string">&#39;P&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">class</span> <span class="token class-name">Child</span> <span class="token keyword">extends</span> <span class="token class-name">Parent</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>Child<span class="token punctuation">)</span> <span class="token operator">===</span> Parent<span class="token punctuation">;</span>        <span class="token comment">// true，构造器链</span>
Child<span class="token punctuation">.</span>tag<span class="token punctuation">;</span>                                       <span class="token comment">// &#39;P&#39;，静态成员可继承</span>
<span class="token class-name">Child</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span>__proto__ <span class="token operator">===</span> <span class="token class-name">Parent</span><span class="token punctuation">.</span>prototype<span class="token punctuation">;</span>  <span class="token comment">// true，实例链</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>extends</code> 后面可以跟表达式吗？答：可以，<code>class A extends mixin(Base) {}</code>，返回值必须是构造函数或 <code>null</code>。</li><li>陷阱：说「<code>class</code> 是全新的继承机制，和原型链无关」。它完全建立在原型链之上。</li></ul><h3 id="q42-class-和函数构造函数有哪些区别" tabindex="-1"><a class="header-anchor" href="#q42-class-和函数构造函数有哪些区别" aria-hidden="true">#</a> Q42 <code>class</code> 和函数构造函数有哪些区别？</h3><p><strong>考察点</strong>：对照题，考察提升、严格模式、可枚举性、<code>new.target</code> 这些细节。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>class</code> 不能当普通函数调用、内部默认严格模式、声明有 TDZ 不提升、原型方法不可枚举，并且天然支持 <code>new.target</code>、静态成员与私有字段。</p></blockquote><table><thead><tr><th>维度</th><th>函数构造函数</th><th><code>class</code></th></tr></thead><tbody><tr><td>调用方式</td><td><code>Fn()</code>、<code>new Fn()</code> 都行</td><td>只能 <code>new</code>，否则 TypeError</td></tr><tr><td>提升</td><td>函数声明整体提升</td><td>有 TDZ，声明前不可用</td></tr><tr><td>严格模式</td><td>看外层</td><td>内部始终严格</td></tr><tr><td>原型方法可枚举性</td><td><code>enumerable: true</code></td><td><code>enumerable: false</code></td></tr><tr><td>重复声明</td><td>允许</td><td>报 SyntaxError</td></tr><tr><td>私有字段</td><td>无</td><td><code>#field</code></td></tr></tbody></table><ol><li>可枚举性差异的实操影响：<code>for...in</code> 或 <code>Object.keys</code> 不会遍历到 <code>class</code> 的方法，写通用工具函数时要记得这一点。</li><li><code>class</code> 是「一等公民式的语法糖 + 更强的约束」，性能上并不比函数快，只是更不容易写错。</li><li>混用注意：把 <code>class</code> 的方法取出来单独调用，<code>this</code> 一样会丢，和普通函数没有区别。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>class</code> 声明会提升吗？答：会被登记但不初始化，声明前访问抛 <code>ReferenceError</code>，与 <code>let</code> 一致。</li><li>陷阱：说「<code>class</code> 就是函数，所以可以直接 <code>Person()</code> 调用」，会立刻被一行代码证伪。</li></ul><h3 id="q43-super-的本质是什么" tabindex="-1"><a class="header-anchor" href="#q43-super-的本质是什么" aria-hidden="true">#</a> Q43 <code>super</code> 的本质是什么？</h3><p><strong>考察点</strong>：深挖题，考察 <code>super</code> 与 <code>this</code> 的区别，以及 <code>[[HomeObject]]</code> 这个内部槽。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>super</code> 是静态解析的：<code>super()</code> 调用父类构造函数并把结果作为当前实例，<code>super.method()</code> 是在「方法定义时的原型」上找方法、但用当前的 <code>this</code> 执行。</p></blockquote><ol><li><code>super</code> 的查找位置由 <code>[[HomeObject]]</code> 决定——即方法被定义在哪个对象/类的原型上，与调用点无关，所以把方法取出来单独调用也不影响 <code>super</code>。</li><li><code>super.method()</code> 等价于 <code>Reflect.get(Object.getPrototypeOf(homeObject), &#39;method&#39;, this)</code>：<strong>方法从父类取，<code>this</code> 仍是子类实例</strong>，这是它和 <code>Parent.prototype.method.call(this)</code> 的等价之处。</li><li><code>super()</code> 特殊：它执行父类构造函数，实例对象是在这一步行创建的，所以在 <code>super()</code> 之前访问 <code>this</code> 会抛错。</li><li>注意 <code>super</code> 只能在类或对象方法（简写方法）内使用，箭头函数里可以「借用」外层的 <code>super</code> 绑定，但不能自己用。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">class</span> <span class="token class-name">Parent</span> <span class="token punctuation">{</span> <span class="token function">say</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">parent:</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span>
<span class="token keyword">class</span> <span class="token class-name">Child</span> <span class="token keyword">extends</span> <span class="token class-name">Parent</span> <span class="token punctuation">{</span>
  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">super</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&#39;child&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">say</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">say</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>   <span class="token comment">// 方法来自 Parent.prototype，this 是 Child 实例</span>
<span class="token punctuation">}</span>
<span class="token keyword">new</span> <span class="token class-name">Child</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">say</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;parent:child&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>super</code> 和 <code>this</code> 谁先有？答：<code>super()</code> 先执行并创建实例，<code>this</code> 才能被访问；这也是子类构造器必须在用 <code>this</code> 前调用 <code>super()</code> 的原因。</li><li>陷阱：以为 <code>super</code> 像变量一样是在运行时沿作用域链找。它是编译期确定位置、绑定到 <code>[[HomeObject]]</code> 的。</li></ul><h3 id="q44-object-getprototypeof、setprototypeof-和-proto-该怎么选" tabindex="-1"><a class="header-anchor" href="#q44-object-getprototypeof、setprototypeof-和-proto-该怎么选" aria-hidden="true">#</a> Q44 <code>Object.getPrototypeOf</code>、<code>setPrototypeOf</code> 和 <code>__proto__</code> 该怎么选？</h3><p><strong>考察点</strong>：考察标准 API 与历史遗留写法的取舍，以及性能意识。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：读原型用 <code>Object.getPrototypeOf</code>，设置原型优先用 <code>Object.create</code> 在创建时指定，<code>Object.setPrototypeOf</code> 有性能代价要少用，<code>__proto__</code> 只在调试或兼容老代码时出现。</p></blockquote><ol><li><code>__proto__</code> 是定义在 <code>Object.prototype</code> 上的访问器，不是对象自身属性；<code>Object.create(null)</code> 的对象连它都没有，代码会直接报错。</li><li><code>Object.setPrototypeOf</code> 会破坏引擎对对象形状（隐藏类）的优化，规范明确说它慢，禁止在热路径反复调用。</li><li>需要「基于某个原型造对象」时用 <code>Object.create(proto)</code> 一步到位，等价于新建 + 设置，但引擎可以按最优路径处理。</li><li><code>Reflect.getPrototypeOf</code> 与 <code>Object.getPrototypeOf</code> 行为相近，区别是对非对象参数：前者抛 TypeError，后者做类型转换。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> proto <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token function">hello</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string">&#39;hi&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> obj <span class="token operator">=</span> Object<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span>proto<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 推荐：创建时指定原型</span>
Object<span class="token punctuation">.</span><span class="token function">getPrototypeOf</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span> <span class="token operator">===</span> proto<span class="token punctuation">;</span> <span class="token comment">// true</span>
Object<span class="token punctuation">.</span><span class="token function">setPrototypeOf</span><span class="token punctuation">(</span>obj<span class="token punctuation">,</span> <span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// 不推荐在热路径使用</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>Object.setPrototypeOf</code> 什么时候还能用？答：一次性初始化、极少数需要动态改变行为的库代码；能用 <code>class</code> / <code>Object.create</code> 就别用它。</li><li>陷阱：用 <code>obj.__proto__ = proto</code> 赋值。它在无原型对象上不生效（只是普通属性赋值），行为不一致。</li></ul><h3 id="q45-垃圾回收机制是怎么回事-标记清除和引用计数有什么区别" tabindex="-1"><a class="header-anchor" href="#q45-垃圾回收机制是怎么回事-标记清除和引用计数有什么区别" aria-hidden="true">#</a> Q45 垃圾回收机制是怎么回事？标记清除和引用计数有什么区别？</h3><p><strong>考察点</strong>：考察 GC 的基本模型，重点在「循环引用」这一经典差异。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：现代 JS 引擎用标记清除（Mark-and-Sweep）：从根对象出发标记所有可达对象，剩下的不可达对象回收；引用计数则按引用数为 0 回收，遇到循环引用会永久泄漏，所以早被淘汰。</p></blockquote><ol><li>根对象包括全局对象、当前调用栈上的局部变量、闭包引用等，只要能顺着引用链走到，就算可达。</li><li>标记清除的优点：天然解决循环引用——两个对象互相引用但都不被根引用时，都不可达，一起回收。</li><li>引用计数的缺点正是循环引用：<code>a.b = b; b.a = a</code> 且没有外部引用时，引用数都是 1，永远回收不掉，这是老 IE 泄漏的根源。</li><li>V8 的实现更细：分代回收（新生代用 Scavenge 复制算法、老生代用标记清除与标记整理），配合增量标记与并发回收减少停顿。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：怎么主动触发 GC？答：浏览器不给 API，DevTools 里可以点垃圾桶图标；Node 下用 <code>--expose-gc</code> 后在调试时调用。</li><li>陷阱：说「引用计数还在用」。它在 JS 引擎里已被标记清除替代，只有部分宿主对象或旧实现残留。</li></ul><h3 id="q46-日常开发里最常见的内存泄漏场景有哪些" tabindex="-1"><a class="header-anchor" href="#q46-日常开发里最常见的内存泄漏场景有哪些" aria-hidden="true">#</a> Q46 日常开发里最常见的内存泄漏场景有哪些？</h3><p><strong>考察点</strong>：考察能否把 GC 知识落到真实排障上，是区分「背概念」和「有经验」的题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：常见泄漏有五类：意外的全局变量、未清理的定时器与事件监听、闭包持有的无用大对象、脱离文档却仍被引用的 DOM 节点、只增不减的缓存。</p></blockquote><ol><li>意外全局变量：忘记声明或用 <code>this</code> 在非严格模式下创建属性，数据永远挂在 <code>window</code> 上。</li><li>未清理的定时器/监听：<code>setInterval</code> 不 <code>clearInterval</code>，<code>addEventListener</code> 不 <code>removeEventListener</code>，回调引用的整条作用域都无法回收（SPA 频繁切换路由时尤其明显）。</li><li>游离 DOM：节点已从文档移除，但 JS 变量或闭包仍持有引用，DevTools 里表现为 <code>Detached HTMLElement</code>。</li><li>缓存与集合：模块级 <code>Map</code>/数组当缓存只存不删、频繁增删的 <code>Map</code> 不如 <code>WeakMap</code> 合适、事件总线上注册的函数从不注销。</li><li>排查思路：Memory 面板拍三次快照做对比，或录制 Allocation instrumentation 时间线，重点看对象数是否持续增长、有没有意外保留链（Retainers）。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：单页应用最典型的泄漏是什么？答：路由切换时旧页面的定时器、事件总线订阅、全局状态里的引用没有清理。</li><li>陷阱：把「内存占用高」等同于泄漏。泄漏的定义是「持续增长且不再释放」，缓存变大是正常现象。</li></ul><h3 id="q47-weakmap-为什么能避免内存泄漏" tabindex="-1"><a class="header-anchor" href="#q47-weakmap-为什么能避免内存泄漏" aria-hidden="true">#</a> Q47 <code>WeakMap</code> 为什么能避免内存泄漏？</h3><p><strong>考察点</strong>：深挖题，考察弱引用的语义及其代价（不可枚举），以及实际使用场景。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>WeakMap</code> 的键是弱引用，不会阻止键对象被垃圾回收；键对象一旦不可达，整条键值记录会被自动移除，所以不需要手动 <code>delete</code> 也不会拖住内存。</p></blockquote><ol><li>对比 <code>Map</code>：<code>Map</code> 强引用键和值，只要 Map 本身可达，键对象就永远活着，用它缓存 DOM 节点或组件实例必然泄漏。</li><li>弱引用的代价：不能遍历，没有 <code>keys</code>/<code>values</code>/<code>entries</code>，也没有 <code>size</code>，因为条目数量随时可能因 GC 变化——这是规范刻意的限制。</li><li>约束：键必须是对象（或非注册的 Symbol），原始值不行。</li><li>典型用法：给对象挂私有数据与元信息（<code>WeakMap&lt;instance, {count:0}&gt;</code>）、DOM 节点到数据的映射、对象缓存；Vue3 内部就用 <code>WeakMap</code> 维护原始对象与响应式代理的映射关系。</li></ol><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> priv <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">WeakMap</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">class</span> <span class="token class-name">Counter</span> <span class="token punctuation">{</span>
  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> priv<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">count</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
  <span class="token function">inc</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token operator">++</span>priv<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">.</span>count<span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
<span class="token comment">// 实例被回收后，WeakMap 里的记录自动消失，无需手动清理</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>WeakSet</code> 呢？答：同理，元素是弱引用，常用来标记「已处理过的对象」而不产生泄漏。</li><li>陷阱：说「<code>WeakMap</code> 会自动清理所以一定能防泄漏」。如果值本身被外部强引用，或者键一直被别处持有，一样不会释放。</li></ul><h3 id="q48-线上怀疑内存泄漏-你具体怎么排查和处理" tabindex="-1"><a class="header-anchor" href="#q48-线上怀疑内存泄漏-你具体怎么排查和处理" aria-hidden="true">#</a> Q48 线上怀疑内存泄漏，你具体怎么排查和处理？</h3><p><strong>考察点</strong>：综合题，考察是否有可执行的排障步骤，而不是只罗列名词。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：先用 Performance/Memory 面板确认「内存曲线是否持续上升且 GC 后不回落」，再用堆快照对比定位增长的对象与保留链，找到持有它的代码（监听、定时器、缓存、闭包）后清理。</p></blockquote><ol><li>第一步确认现象：Performance 里录制包含反复操作的时间段，观察 JS Heap 是否呈锯齿上升、每次 GC 后基线是否抬高；也可用 Memory 的 Allocation instrumentation 看分配热点。</li><li>第二步定位对象：做三次堆快照（操作前、操作后、再次操作后），在 Comparison 视图里按 <code>Delta</code> 排序找持续增长的构造函数；对疑似 DOM 用 <code>Detached</code> 过滤，直接搜 <code>Detached HTMLElement</code>。</li><li>第三步找根因：在快照里看目标对象的 Retainers（保留链），一直追到最外层的持有者，通常就是忘了摘除的监听、定时器、全局缓存或事件总线。</li><li>第四步修复与验证：组件卸载时统一清理（<code>clearInterval</code>、<code>removeEventListener</code>、<code>abortController.abort()</code>、订阅退订），缓存改用 <code>WeakMap</code>，再重复第 1 步确认曲线回落。</li><li>Node 侧思路一致，配合 <code>--inspect</code> 抓堆快照、<code>process.memoryUsage()</code> 观察 RSS 趋势，或用 <code>clinic</code>/<code>heapdump</code> 定位。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么要拍三次快照？答：两次只能看到差异，三次能确认「持续增长」的趋势，排除一次性初始化的干扰。</li><li>陷阱：不做手动 GC 就对比快照，会把待回收的垃圾对象误判成泄漏。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>作用域是静态的，看代码书写位置；<code>this</code> 是动态的，看调用方式，两者是两套完全独立的机制。</li><li><code>var</code> 是函数作用域、会提升为 <code>undefined</code>；<code>let</code>/<code>const</code> 是块级作用域、有 TDZ——循环打印同一个值的根因就在这里。</li><li>闭包 = 函数 + 定义时的词法环境，捕获的是变量本身而不是值的快照；它是特性，不是内存泄漏。</li><li><code>this</code> 优先级：<code>new</code> &gt; 显式绑定 &gt; 隐式绑定 &gt; 默认绑定；箭头函数不参与，直接取定义时的外层 <code>this</code>。</li><li><code>new</code> 四步：建对象、连原型、执行构造函数、按返回值规则返回；构造函数返回对象会覆盖默认实例。</li><li>原型查找从自身开始沿 <code>[[Prototype]]</code> 向上，终点是 <code>null</code>；<code>instanceof</code> 只是查原型链，不是类型检测。</li><li>继承的最佳实践是寄生组合继承，<code>class extends</code> 在此之上多加了一条子类构造函数指向父类构造函数的静态链。</li><li>内存泄漏的本质是「不再需要却仍然可达」，排查靠堆快照对比与保留链，修复靠及时清理监听、定时器与缓存（长期缓存优先 <code>WeakMap</code>）。</li></ul>`,378);function p(l,i){return s(),a("div",null,[c,o(" COUNT: 48 ")])}const u=n(t,[["render",p],["__file","02-js-scope-closure-this-prototype.html.vue"]]);export{u as default};
